alter type public.ledger_entry_type add value if not exists 'payment_credit';
create type public.payment_method_type as enum ('bank_transfer','pago_movil','zelle','cash','international_transfer','paypal_manual','other');
create type public.payment_status as enum ('draft','submitted','under_review','correction_requested','approved','rejected','reversed');

create table public.condominium_payment_methods (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id) on delete cascade, method_type public.payment_method_type not null, display_name text not null, currency_code text not null check(currency_code~'^[A-Z]{3}$'), account_holder text, bank_name text, account_identifier_masked text, phone_masked text, email_masked text, instructions text, requires_reference boolean not null default false, requires_proof boolean not null default false, is_active boolean not null default true, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(condominium_id,display_name), unique(id,condominium_id)
);
create table public.payments (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), unit_id uuid not null, submitted_by_user_id uuid not null references auth.users(id), submitted_for_person_id uuid references public.people(id), payment_method_id uuid not null, status public.payment_status not null default 'draft', payment_date date not null, original_amount numeric(18,2) not null check(original_amount>0 and original_amount=round(original_amount,2)), original_currency_code text not null check(original_currency_code~'^[A-Z]{3}$'), payer_name text not null, reference text, notes text, idempotency_key text not null, submitted_at timestamptz, reviewed_by uuid references auth.users(id), reviewed_at timestamptz, approved_by uuid references auth.users(id), approved_at timestamptz, rejected_by uuid references auth.users(id), rejected_at timestamptz, rejection_reason text, correction_reason text, reversed_by uuid references auth.users(id), reversed_at timestamptz, reversal_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(condominium_id,idempotency_key), unique(id,condominium_id,unit_id), unique(id,condominium_id,unit_id,original_currency_code), foreign key(unit_id,condominium_id) references public.units(id,condominium_id), foreign key(payment_method_id,condominium_id) references public.condominium_payment_methods(id,condominium_id)
);
create table public.payment_proofs (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), payment_id uuid not null, object_key text not null check(object_key !~ '[^a-zA-Z0-9/_-]'), original_filename text not null, content_type text not null, size_bytes bigint not null check(size_bytes>0 and size_bytes<=10485760), sha256 text not null, uploaded_by uuid not null references auth.users(id), created_at timestamptz not null default now(), superseded_at timestamptz, superseded_by_proof_id uuid, unique(id,condominium_id,payment_id), foreign key(payment_id,condominium_id) references public.payments(id,condominium_id)
);
create unique index payment_proofs_one_active on public.payment_proofs(payment_id) where superseded_at is null;
create table public.payment_allocations (
 id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), payment_id uuid not null, receivable_item_id uuid not null, payment_currency_code text not null check(payment_currency_code~'^[A-Z]{3}$'), receivable_currency_code text not null check(receivable_currency_code~'^[A-Z]{3}$'), payment_amount numeric(18,2) not null check(payment_amount>0), receivable_amount numeric(18,2) not null check(receivable_amount>0), receivable_per_payment_rate numeric(24,10), fx_rate_source text, fx_rate_at timestamptz, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(id,condominium_id,payment_id), foreign key(payment_id,condominium_id) references public.payments(id,condominium_id), foreign key(receivable_item_id,condominium_id) references public.receivable_items(id,condominium_id), check((payment_currency_code=receivable_currency_code and (receivable_per_payment_rate is null or receivable_per_payment_rate=1) and payment_amount=receivable_amount) or (payment_currency_code<>receivable_currency_code and receivable_per_payment_rate>0 and receivable_amount=round(payment_amount*receivable_per_payment_rate,2)))
);
create table public.payment_receipt_sequences (condominium_id uuid not null references public.condominiums(id), year integer not null, last_number integer not null default 0, primary key(condominium_id,year));
create table public.payment_receipts (id uuid primary key default gen_random_uuid(), condominium_id uuid not null references public.condominiums(id), payment_id uuid not null unique, receipt_number text not null, sequence_year integer not null, sequence_number integer not null, issued_at timestamptz not null default now(), issued_by uuid not null references auth.users(id), snapshot jsonb not null, created_at timestamptz not null default now(), unique(condominium_id,receipt_number), foreign key(payment_id,condominium_id) references public.payments(id,condominium_id));
alter table public.receivable_ledger_entries add column payment_id uuid, add column payment_allocation_id uuid;
alter table public.receivable_ledger_entries add constraint ledger_payment_tenant_fkey foreign key(payment_id,condominium_id,unit_id) references public.payments(id,condominium_id,unit_id), add constraint ledger_allocation_tenant_fkey foreign key(payment_allocation_id,condominium_id,payment_id) references public.payment_allocations(id,condominium_id,payment_id);
create unique index ledger_allocation_credit_once on public.receivable_ledger_entries(payment_allocation_id) where payment_allocation_id is not null;
create unique index ledger_unallocated_payment_credit_once on public.receivable_ledger_entries(payment_id,currency_code) where payment_id is not null and payment_allocation_id is null and entry_type='payment_credit';

create function public.can_submit_payment(target_unit uuid) returns boolean language sql stable security definer set search_path=public set row_security=off as $$ select public.can_manage_people(u.condominium_id) or exists(select 1 from public.unit_owners o join public.people p on p.id=o.person_id where o.unit_id=target_unit and p.auth_user_id=auth.uid()) or exists(select 1 from public.unit_occupancies o join public.people p on p.id=o.person_id where o.unit_id=target_unit and p.auth_user_id=auth.uid()) from public.units u where u.id=target_unit $$;
create function public.can_review_payments(target uuid) returns boolean language sql stable security definer set search_path=public set row_security=off as $$ select public.can_manage_receivables(target) or exists(select 1 from public.condominium_memberships where condominium_id=target and user_id=auth.uid() and role='payment_reviewer') $$;
revoke all on function public.can_submit_payment(uuid),public.can_review_payments(uuid) from public; grant execute on function public.can_submit_payment(uuid),public.can_review_payments(uuid) to authenticated,service_role;

create function public.payment_immutable() returns trigger language plpgsql as $$ begin if old.status in ('approved','reversed') then raise exception 'financial payment is immutable'; end if; if tg_op='delete' then raise exception 'payments cannot be deleted'; end if; if old.status not in ('draft','correction_requested') and (new.original_amount,new.original_currency_code,new.payment_method_id,new.payment_date,new.payer_name,new.reference,new.notes) is distinct from (old.original_amount,old.original_currency_code,old.payment_method_id,old.payment_date,old.payer_name,old.reference,old.notes) then raise exception 'submitted payment financial data is locked'; end if; return new; end $$;
create trigger payments_immutable before update or delete on public.payments for each row execute function public.payment_immutable();
create function public.payment_allocations_immutable() returns trigger language plpgsql as $$ begin raise exception 'payment allocations are immutable'; end $$;
create trigger allocations_immutable before update or delete on public.payment_allocations for each row execute function public.payment_allocations_immutable();

alter table public.condominium_payment_methods enable row level security; alter table public.payments enable row level security; alter table public.payment_proofs enable row level security; alter table public.payment_allocations enable row level security; alter table public.payment_receipts enable row level security;
create policy methods_read on public.condominium_payment_methods for select using(is_active or public.can_manage_receivables(condominium_id) or exists(select 1 from public.condominium_memberships where condominium_id=condominium_payment_methods.condominium_id and user_id=auth.uid() and role='assistant'));
create policy methods_write on public.condominium_payment_methods for all using(public.can_manage_receivables(condominium_id)) with check(public.can_manage_receivables(condominium_id));
create policy payments_read on public.payments for select using(public.can_review_payments(condominium_id) or public.can_submit_payment(unit_id));
create policy proofs_read on public.payment_proofs for select using(exists(select 1 from public.payments p where p.id=payment_id and (public.can_review_payments(p.condominium_id) or public.can_submit_payment(p.unit_id))));
create policy allocations_read on public.payment_allocations for select using(exists(select 1 from public.payments p where p.id=payment_id and (public.can_review_payments(p.condominium_id) or public.can_submit_payment(p.unit_id))));
create policy receipts_read on public.payment_receipts for select using(exists(select 1 from public.payments p where p.id=payment_id and (public.can_review_payments(p.condominium_id) or public.can_submit_payment(p.unit_id))));
revoke insert,update,delete on public.payments,public.payment_proofs,public.payment_allocations,public.payment_receipts from authenticated;

create function public.create_payment_draft(target uuid,target_unit uuid,target_method uuid,payment_on date,amount numeric,currency text,payer text,reference_value text,notes_value text,key text) returns public.payments language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; begin if auth.uid() is null or not public.can_submit_payment(target_unit) or amount<=0 or amount<>round(amount,2) or currency !~ '^[A-Z]{3}$' then raise exception 'invalid payment'; end if; select * into p from public.payments where condominium_id=target and idempotency_key=key; if found then return p; end if; insert into public.payments(condominium_id,unit_id,submitted_by_user_id,payment_method_id,payment_date,original_amount,original_currency_code,payer_name,reference,notes,idempotency_key) values(target,target_unit,auth.uid(),target_method,payment_on,amount,currency,payer,reference_value,notes_value,key) returning * into p; return p; end $$;
create function public.update_payment_draft(target uuid,target_payment uuid,target_method uuid,payment_on date,amount numeric,currency text,payer text,reference_value text,notes_value text) returns public.payments language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; begin select * into p from public.payments where id=target_payment and condominium_id=target for update; if p.id is null or p.status not in ('draft','correction_requested') or (p.submitted_by_user_id<>auth.uid() and not public.can_manage_people(target)) then raise exception 'payment update denied'; end if; update public.payments set payment_method_id=target_method,payment_date=payment_on,original_amount=amount,original_currency_code=currency,payer_name=payer,reference=reference_value,notes=notes_value,updated_at=now(),status='draft',correction_reason=null where id=p.id returning * into p; return p; end $$;
create function public.submit_payment(target uuid,target_payment uuid) returns public.payments language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; m public.condominium_payment_methods; begin select * into p from public.payments where id=target_payment and condominium_id=target for update; select * into m from public.condominium_payment_methods where id=p.payment_method_id; if p.status not in ('draft','correction_requested') or (p.submitted_by_user_id<>auth.uid() and not public.can_manage_people(target)) or (m.requires_reference and coalesce(trim(p.reference),'')='') or (m.requires_proof and not exists(select 1 from public.payment_proofs where payment_id=p.id and superseded_at is null)) then raise exception 'payment cannot be submitted'; end if; update public.payments set status='submitted',submitted_at=now(),updated_at=now() where id=p.id returning * into p; return p; end $$;
create function public.payment_transition(target uuid,target_payment uuid,next_status public.payment_status,reason text default null) returns public.payments language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; begin if not public.can_review_payments(target) then raise exception 'review denied'; end if; select * into p from public.payments where id=target_payment and condominium_id=target for update; if next_status='under_review' and p.status='submitted' then update public.payments set status=next_status,reviewed_by=auth.uid(),reviewed_at=now() where id=p.id returning * into p; elsif next_status='correction_requested' and p.status in ('submitted','under_review') and coalesce(trim(reason),'')<>'' then update public.payments set status=next_status,correction_reason=trim(reason) where id=p.id returning * into p; elsif next_status='rejected' and p.status in ('submitted','under_review') and coalesce(trim(reason),'')<>'' then update public.payments set status=next_status,rejected_by=auth.uid(),rejected_at=now(),rejection_reason=trim(reason) where id=p.id returning * into p; else raise exception 'invalid transition'; end if; return p; end $$;
create function public.approve_payment(target uuid,target_payment uuid,allocations jsonb) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; a jsonb; item public.receivable_items; allocation public.payment_allocations; used numeric:=0; remaining numeric; year_value integer:=extract(year from current_date); seq integer; snapshot_value jsonb; begin if not public.can_review_payments(target) then raise exception 'approval denied'; end if; select * into p from public.payments where id=target_payment and condominium_id=target for update; if p.status='approved' then return (select jsonb_build_object('payment_id',p.id,'receipt_number',r.receipt_number,'idempotent',true) from public.payment_receipts r where r.payment_id=p.id); end if; if p.status not in ('submitted','under_review') then raise exception 'invalid payment status'; end if; for a in select value from jsonb_array_elements(allocations) loop select * into item from public.receivable_items where id=(a->>'receivable_item_id')::uuid and condominium_id=target and unit_id=p.unit_id and lifecycle_status='active' for update; if item.id is null or (a->>'payment_amount')::numeric<=0 or (a->>'receivable_amount')::numeric<=0 then raise exception 'invalid allocation'; end if; if (a->>'payment_currency_code')<>p.original_currency_code or ((a->>'receivable_currency_code')<>item.currency_code) or (select coalesce(sum(case direction when 'debit' then amount else -amount end),0) from public.receivable_ledger_entries where receivable_item_id=item.id) < (a->>'receivable_amount')::numeric then raise exception 'over allocation'; end if; insert into public.payment_allocations(condominium_id,payment_id,receivable_item_id,payment_currency_code,receivable_currency_code,payment_amount,receivable_amount,receivable_per_payment_rate,fx_rate_source,fx_rate_at,created_by) values(target,p.id,item.id,p.original_currency_code,item.currency_code,(a->>'payment_amount')::numeric,(a->>'receivable_amount')::numeric,nullif(a->>'receivable_per_payment_rate','')::numeric,a->>'fx_rate_source',nullif(a->>'fx_rate_at','')::timestamptz,auth.uid()) returning * into allocation; insert into public.receivable_ledger_entries(condominium_id,unit_id,receivable_item_id,entry_type,direction,amount,currency_code,effective_date,description,payment_id,payment_allocation_id,created_by) values(target,p.unit_id,item.id,'payment_credit','credit',allocation.receivable_amount,item.currency_code,p.payment_date,'Payment application',p.id,allocation.id,auth.uid()); used:=used+allocation.payment_amount; end loop; if used>p.original_amount then raise exception 'payment over applied'; end if; remaining:=p.original_amount-used; if remaining>0 then insert into public.receivable_ledger_entries(condominium_id,unit_id,entry_type,direction,amount,currency_code,effective_date,description,payment_id,created_by) values(target,p.unit_id,'payment_credit','credit',remaining,p.original_currency_code,p.payment_date,'Unapplied payment credit',p.id,auth.uid()); end if; insert into public.payment_receipt_sequences(condominium_id,year,last_number) values(target,year_value,0) on conflict(condominium_id,year) do nothing; update public.payment_receipt_sequences set last_number=last_number+1 where condominium_id=target and year=year_value returning last_number into seq; snapshot_value:=jsonb_build_object('payment',jsonb_build_object('amount',p.original_amount,'currency',p.original_currency_code,'payer',p.payer_name,'date',p.payment_date,'reference',p.reference),'allocations',coalesce((select jsonb_agg(to_jsonb(x)) from public.payment_allocations x where x.payment_id=p.id),'[]'::jsonb),'unapplied_credit',remaining,'approved_by',auth.uid()); insert into public.payment_receipts(condominium_id,payment_id,receipt_number,sequence_year,sequence_number,issued_by,snapshot) values(target,p.id,format('REC-%s-%s',year_value,lpad(seq::text,6,'0')),year_value,seq,auth.uid(),snapshot_value); update public.payments set status='approved',approved_by=auth.uid(),approved_at=now(),updated_at=now() where id=p.id; return jsonb_build_object('payment_id',p.id,'receipt_number',format('REC-%s-%s',year_value,lpad(seq::text,6,'0')),'unapplied_credit',remaining); end $$;
create function public.reverse_payment(target uuid,target_payment uuid,reason text) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; e public.receivable_ledger_entries; begin if not public.can_review_payments(target) or coalesce(trim(reason),'')='' then raise exception 'reversal denied'; end if; select * into p from public.payments where id=target_payment and condominium_id=target for update; if p.status<>'approved' then raise exception 'payment not reversible'; end if; for e in select * from public.receivable_ledger_entries where payment_id=p.id and entry_type='payment_credit' for update loop insert into public.receivable_ledger_entries(condominium_id,unit_id,receivable_item_id,entry_type,direction,amount,currency_code,effective_date,description,reversal_of_entry_id,payment_id,created_by) values(e.condominium_id,e.unit_id,e.receivable_item_id,'reversal','debit',e.amount,e.currency_code,current_date,trim(reason),e.id,p.id,auth.uid()); end loop; update public.payments set status='reversed',reversed_by=auth.uid(),reversed_at=now(),reversal_reason=trim(reason) where id=p.id; return jsonb_build_object('payment_id',p.id,'status','reversed'); end $$;
create function public.record_payment_proof(target uuid,target_payment uuid,key_value text,filename text,mime text,bytes bigint,hash text) returns public.payment_proofs language plpgsql security definer set search_path=public set row_security=off as $$ declare p public.payments; proof public.payment_proofs; previous uuid; begin select * into p from public.payments where id=target_payment and condominium_id=target for update; if p.id is null or p.status='approved' or not public.can_submit_payment(p.unit_id) then raise exception 'proof upload denied'; end if; select id into previous from public.payment_proofs where payment_id=p.id and superseded_at is null for update; insert into public.payment_proofs(condominium_id,payment_id,object_key,original_filename,content_type,size_bytes,sha256,uploaded_by) values(target,p.id,key_value,filename,mime,bytes,hash,auth.uid()) returning * into proof; if previous is not null then update public.payment_proofs set superseded_at=now(),superseded_by_proof_id=proof.id where id=previous; end if; return proof; end $$;
revoke all on function public.create_payment_draft(uuid,uuid,uuid,date,numeric,text,text,text,text,text),public.update_payment_draft(uuid,uuid,uuid,date,numeric,text,text,text,text),public.submit_payment(uuid,uuid),public.payment_transition(uuid,uuid,public.payment_status,text),public.approve_payment(uuid,uuid,jsonb),public.reverse_payment(uuid,uuid,text),public.record_payment_proof(uuid,uuid,text,text,text,bigint,text) from public; grant execute on function public.create_payment_draft(uuid,uuid,uuid,date,numeric,text,text,text,text,text),public.update_payment_draft(uuid,uuid,uuid,date,numeric,text,text,text,text),public.submit_payment(uuid,uuid),public.payment_transition(uuid,uuid,public.payment_status,text),public.approve_payment(uuid,uuid,jsonb),public.reverse_payment(uuid,uuid,text),public.record_payment_proof(uuid,uuid,text,text,text,bigint,text) to authenticated,service_role;
